-- who can read an A2 job: the same RLS as Phase A (one row for members, zero for non-members, anon refused)
INSERT INTO jobs (id, company_id, job_no, status) VALUES ('b1000000-0000-0000-0000-0000000ea201', 'c1000000-0000-0000-0000-000000000001', 'WO-A2R1', 'Open');
INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date) VALUES
  ('f1000000-0000-0000-0000-0000000ea201', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 1, 'S', '2026-03-09', '2026-03-13'),
  ('f1000000-0000-0000-0000-0000000ea202', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 2, 'C1', '2026-03-09', '2026-03-13'),
  ('f1000000-0000-0000-0000-0000000ea203', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 3, 'X', '2026-03-09', '2026-03-11');
UPDATE job_tasks SET parent_task_id = 'f1000000-0000-0000-0000-0000000ea201' WHERE id = 'f1000000-0000-0000-0000-0000000ea202';
INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days, link_type)
VALUES ('c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 'f1000000-0000-0000-0000-0000000ea203', 'f1000000-0000-0000-0000-0000000ea201', 0, 'SS');
DO $$
DECLARE ops uuid := '11111111-1111-1111-1111-111111111111'; ops2 uuid := '77777777-7777-7777-7777-777777777777';
  viewr uuid := '22222222-2222-2222-2222-222222222222'; fin uuid := '13131313-1313-1313-1313-131313131313';
  clnt uuid := 'cccccccc-cccc-cccc-cccc-cccccccccccc';
  q text := 'SELECT 1 FROM job_schedule_status(''b1000000-0000-0000-0000-0000000ea201''::uuid, ''2026-03-02'')';
BEGIN
  PERFORM t_expect('caller: operations_tech gets exactly one row for a hierarchy + SS-link job', t_count('authenticated', ops, q), 'n:1');
  PERFORM t_expect('caller: viewer gets one row', t_count('authenticated', viewr, q), 'n:1');
  PERFORM t_expect('caller: a member without work-order atoms gets zero rows', t_count('authenticated', fin, q), 'n:0');
  PERFORM t_expect('caller: a JWT with no company membership gets zero rows', t_count('authenticated', clnt, q), 'n:0');
  PERFORM t_expect('caller: another company gets zero rows', t_count('authenticated', ops2, q), 'n:0');
  PERFORM t_expect('caller: anon cannot call it', t_count('anon', NULL, q), 'err:42501');
  PERFORM t_expect('caller: the value an authenticated caller gets equals the owner value (SS from the summary: X starts with its leaf)',
    t_val('authenticated', ops, 'SELECT status || ''|'' || forecast_end::text FROM job_schedule_status(''b1000000-0000-0000-0000-0000000ea201''::uuid, ''2026-03-02'')'),
    (SELECT status || '|' || forecast_end::text FROM job_schedule_status('b1000000-0000-0000-0000-0000000ea201'::uuid, '2026-03-02')));
END $$;

-- ===== (4) link types the CHECK constraint refuses behave as FS (constraint dropped inside this rolled-back transaction) =====
DO $$
DECLARE cn text;
BEGIN
  SELECT conname INTO cn FROM pg_constraint WHERE conrelid = 'public.job_task_links'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%link_type%';
  PERFORM t_expect('unknown type: the link_type CHECK exists (so production data can never hold an unknown type)', (coalesce(cn, 'none') <> 'none')::text, 'true');
  PERFORM t_expect('unknown type: the CHECK lists exactly FS, SS, FF, SF',
    (SELECT (d LIKE '%''FS''%' AND d LIKE '%''SS''%' AND d LIKE '%''FF''%' AND d LIKE '%''SF''%' AND d NOT LIKE '%''ZZ''%')::text FROM (SELECT pg_get_constraintdef(oid) AS d FROM pg_constraint WHERE conname = cn) x), 'true');
  EXECUTE format('ALTER TABLE job_task_links DROP CONSTRAINT %I', cn);
END $$;
-- ===== (5) M1 (review 2): absurd dates a writer can store must not make the status function raise =====
DO $$
DECLARE
  c1 constant uuid := 'c1000000-0000-0000-0000-000000000001'; j constant uuid := 'b1000000-0000-0000-0000-0000000e9998'; r text;
BEGIN
  INSERT INTO jobs (id, company_id, job_no, status) VALUES (j, c1, 'WO-S9998', 'In Progress');
  INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date, progress) VALUES
    ('f1000000-0000-0000-0000-0000000e9981', c1, j, 1, 'far end', '2026-01-01', '99999-12-31', 0),
    ('f1000000-0000-0000-0000-0000000e9982', c1, j, 2, 'far both', '99998-01-01', '99999-12-31', 50),
    ('f1000000-0000-0000-0000-0000000e9983', c1, j, 3, 'ancient', '0100-01-01', '2026-02-01', 10),
    ('f1000000-0000-0000-0000-0000000e9984', c1, j, 4, 'done far', '2026-01-01', '99999-12-31', 100);
  BEGIN
    SELECT count(*)::text || '|' || (min(forecast_end) IS NOT NULL)::text INTO r FROM job_schedule_status(j, '2026-03-02');
  EXCEPTION WHEN OTHERS THEN r := 'raised: ' || SQLERRM;
  END;
  PERFORM t_expect('m1: dates in year 99999 and year 100 do not make job_schedule_status raise and still give a forecast', r, '1|true');
  DELETE FROM job_tasks WHERE job_id = j AND task_name IN ('far both', 'done far'); UPDATE job_tasks SET end_date = '2026-06-30' WHERE job_id = j AND task_name = 'far end';
  BEGIN SELECT count(*)::text INTO r FROM job_schedule_status(j, '2026-03-02'); EXCEPTION WHEN OTHERS THEN r := 'raised: ' || SQLERRM; END;
  PERFORM t_expect('m1: and still answers after the far dates are edited back', r, '1');
  -- a start date far in the past is clamped too: the forecast of a lone ancient task stays inside the clamp range
  DELETE FROM job_tasks WHERE job_id = j AND task_name = 'far end';
  SELECT (min(forecast_end) >= DATE '2000-01-01')::text INTO r FROM job_schedule_status(j, '2026-03-02');
  PERFORM t_expect('m1: a lone task starting in year 100 forecasts inside the clamp range', r, 'true');
END $$;

-- r3 perf: the passes relax links in dependency order when there is no summary and no link cycle (any order gives the same fixpoint).
-- Oracle: a 60-task DAG with mixed link types, links listed against the direction, in direction, and with a dummy summary that
-- forces the legacy array order (the dummy is a done task under a summary, so it changes no status, forecast or slip).
DO $$
DECLARE tk jsonb; lk_rev jsonb; lk_fwd jsonb; r_rev text; r_fwd text; r_leg text; r_dag text;
BEGIN
  SELECT jsonb_agg(jsonb_build_object('key', 'T' || k, 'sort_order', k, 'start_date', (DATE '2026-03-02' + (k % 5))::text,
                                      'end_date', (DATE '2026-03-02' + (k % 5) + 3)::text) ORDER BY k) INTO tk FROM generate_series(1, 60) k;
  SELECT jsonb_agg(jsonb_build_object('task', 'T' || k, 'pred', 'T' || (1 + (k * 7) % (k - 1)), 'lag', (k % 3) - 1,
                                      'type', (ARRAY['FS', 'SS', 'FF', 'SF'])[1 + k % 4]) ORDER BY k DESC) INTO lk_rev FROM generate_series(2, 60) k;
  SELECT jsonb_agg(l ORDER BY o DESC) INTO lk_fwd FROM jsonb_array_elements(lk_rev) WITH ORDINALITY AS x(l, o);
  r_rev := pg_temp.a2run(jsonb_build_object('today', '2026-03-02', 'job', jsonb_build_object('status', 'In Progress'), 'baselineLocked', false,
                                            'tasks', tk, 'links', lk_rev));
  r_fwd := pg_temp.a2run(jsonb_build_object('today', '2026-03-02', 'job', jsonb_build_object('status', 'In Progress'), 'baselineLocked', false,
                                            'tasks', tk, 'links', lk_fwd));
  r_leg := pg_temp.a2run(jsonb_build_object('today', '2026-03-02', 'job', jsonb_build_object('status', 'In Progress'), 'baselineLocked', false,
                                            'tasks', tk || jsonb_build_array(
                                               jsonb_build_object('key', 'S', 'sort_order', 100),
                                               jsonb_build_object('key', 'Sc', 'sort_order', 101, 'parent', 'S', 'progress', 100,
                                                                  'start_date', '2026-01-01', 'end_date', '2026-01-02')),
                                            'links', lk_rev));
  PERFORM t_expect('r3: the reversed DAG gives a forecast (not an empty result)', (r_rev ~ '^1:[A-Za-z ]+\|20')::text, 'true');
  PERFORM t_expect('r3: link order does not matter (reversed vs forward listing)', r_rev, r_fwd);
  PERFORM t_expect('r3: dependency order equals the legacy array order (a summary forces the latter)', r_rev, r_leg);
END $$;

-- r3 perf, the cases where the link order must NOT change: a pass that never settles stops after n+1 passes with the values so far,
-- and those values depend on the order the links are relaxed in. Expected values are the ones the pre-r3 body (array order) gave.
-- (a) a cyclic link graph (inserted with triggers off: the link trigger refuses cycles) + a reversed chain with lag 300 feeding it.
-- (b) a leaf linked to its own summary (never settles; the link graph itself is acyclic) + the same reversed chain.
DO $$
DECLARE co constant uuid := 'c1000000-0000-0000-0000-000000000001';
BEGIN
  INSERT INTO jobs (id, company_id, job_no, status) VALUES ('b1000000-0000-0000-0000-0000000b0002', co, 'CYC-1', 'Open'), ('b1000000-0000-0000-0000-0000000b0003', co, 'CYC-2', 'Open');
  PERFORM set_config('session_replication_role', 'replica', true);
  INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date)
  SELECT ('e1000000-0000-0000-0000-' || lpad(g::text, 12, '0'))::uuid, co, 'b1000000-0000-0000-0000-0000000b0002', g, 'T' || g, DATE '2026-03-02', DATE '2026-03-04'
    FROM generate_series(1, 6) g;                    -- 1..4 = chain R1..R4, 5 and 6 = the cycle C1, C2
  INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days, link_type)
  SELECT co, 'b1000000-0000-0000-0000-0000000b0002', ('e1000000-0000-0000-0000-' || lpad(a::text, 12, '0'))::uuid, ('e1000000-0000-0000-0000-' || lpad(b::text, 12, '0'))::uuid, lag, 'FS'
    FROM (VALUES (1,2,0,1),(2,3,0,2),(3,4,300,3),(5,6,0,4),(6,5,0,5),(5,1,0,6)) v(a,b,lag,o) ORDER BY o;
  INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date, parent_task_id)
  SELECT ('e2000000-0000-0000-0000-' || lpad(g::text, 12, '0'))::uuid, co, 'b1000000-0000-0000-0000-0000000b0003', g, 'T' || g, DATE '2026-03-02', DATE '2026-03-04',
         CASE WHEN g IN (6, 7) THEN 'e2000000-0000-0000-0000-000000000005'::uuid END
    FROM generate_series(1, 7) g;                    -- 1..4 = chain, 5 = summary S, 6 and 7 = its kids
  INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days, link_type)
  SELECT co, 'b1000000-0000-0000-0000-0000000b0003', ('e2000000-0000-0000-0000-' || lpad(a::text, 12, '0'))::uuid, ('e2000000-0000-0000-0000-' || lpad(b::text, 12, '0'))::uuid, lag, 'FS'
    FROM (VALUES (1,2,0,1),(2,3,0,2),(3,4,300,3),(6,5,0,4),(6,1,0,5)) v(a,b,lag,o) ORDER BY o;
  PERFORM set_config('session_replication_role', 'origin', true);
  PERFORM t_expect('r3: cyclic links keep the array order (non-settling values unchanged)', pg_temp.st('b1000000-0000-0000-0000-0000000b0002', '2026-03-02'), '1:On track|2027-02-07|null');
  PERFORM t_expect('r3: a summary keeps the array order (non-settling values unchanged)', pg_temp.st('b1000000-0000-0000-0000-0000000b0003', '2026-03-02'), '1:On track|2027-01-29|null');
END $$;

-- r3d M2: the harness plants ancestor / descendant links with ONLY job_task_links_hierarchy_guard switched off, and switches it back on
DO $$
BEGIN
  PERFORM t_expect('r3d: the link hierarchy guard is enabled again after the planted-link cases',
    (SELECT tgenabled::text FROM pg_trigger WHERE tgname = 'job_task_links_hierarchy_guard'), 'O');
  PERFORM t_expect('r3d: a stored summary<->kid link (planted) is still evaluated: one status row, no error',
    (pg_temp.a2run('{"today":"2026-03-02","job":{"status":"In Progress"},"baselineLocked":false,"tasks":[{"key":"S","sort_order":1},{"key":"K","sort_order":2,"parent":"S","start_date":"2026-03-02","end_date":"2026-03-04"}],"links":[{"task":"S","pred":"K"}]}'::jsonb) ~ '^1:')::text, 'true');
END $$;

DO $$
BEGIN
  PERFORM t_expect('reference for the unknown-type cases: the same link as FS', pg_temp.a2run($j${"today":"2026-03-02","job":{"status":"In Progress","due_date":null},"baselineLocked":false,"tasks":[{"key":"A","sort_order":10,"start_date":"2026-03-09","end_date":"2026-03-13","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null},{"key":"B","sort_order":20,"start_date":"2026-03-09","end_date":"2026-03-14","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null}],"links":[{"task":"B","pred":"A","lag":2,"type":"FS"}]}$j$::jsonb), '1:On track|2026-03-15|null');
  PERFORM t_expect('unknown link_type ''ZZ'' behaves as FS', pg_temp.a2run($j${"today":"2026-03-02","job":{"status":"In Progress","due_date":null},"baselineLocked":false,"tasks":[{"key":"A","sort_order":10,"start_date":"2026-03-09","end_date":"2026-03-13","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null},{"key":"B","sort_order":20,"start_date":"2026-03-09","end_date":"2026-03-14","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null}],"links":[{"task":"B","pred":"A","lag":2,"type":"ZZ"}]}$j$::jsonb), '1:On track|2026-03-15|null');
  PERFORM t_expect('unknown link_type ''ss'' behaves as FS', pg_temp.a2run($j${"today":"2026-03-02","job":{"status":"In Progress","due_date":null},"baselineLocked":false,"tasks":[{"key":"A","sort_order":10,"start_date":"2026-03-09","end_date":"2026-03-13","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null},{"key":"B","sort_order":20,"start_date":"2026-03-09","end_date":"2026-03-14","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null}],"links":[{"task":"B","pred":"A","lag":2,"type":"ss"}]}$j$::jsonb), '1:On track|2026-03-15|null');
  PERFORM t_expect('unknown link_type ''FS '' behaves as FS', pg_temp.a2run($j${"today":"2026-03-02","job":{"status":"In Progress","due_date":null},"baselineLocked":false,"tasks":[{"key":"A","sort_order":10,"start_date":"2026-03-09","end_date":"2026-03-13","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null},{"key":"B","sort_order":20,"start_date":"2026-03-09","end_date":"2026-03-14","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null}],"links":[{"task":"B","pred":"A","lag":2,"type":"FS "}]}$j$::jsonb), '1:On track|2026-03-15|null');
  PERFORM t_expect('unknown link_type ''XX'' behaves as FS', pg_temp.a2run($j${"today":"2026-03-02","job":{"status":"In Progress","due_date":null},"baselineLocked":false,"tasks":[{"key":"A","sort_order":10,"start_date":"2026-03-09","end_date":"2026-03-13","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null},{"key":"B","sort_order":20,"start_date":"2026-03-09","end_date":"2026-03-14","progress":0,"is_milestone":false,"weight":null,"baseline_start":null,"baseline_end":null}],"links":[{"task":"B","pred":"A","lag":2,"type":"XX"}]}$j$::jsonb), '1:On track|2026-03-15|null');
END $$;
ROLLBACK;
